Ext._define('adm.patrimonio.SuspensaoGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'adm.patrimonio.SuspensaoWindow',

    getToolbar: function(cfg) {
        if(!this._toolbar) {
            this._toolbar = adm.patrimonio.SuspensaoGrid.superclass.getToolbar.call(this, cfg);

            this._toolbar.insert(
                3,
                {
                    text: 'Finalizar',
                    scope: this,
                    handler: this.closeSuspension,
                    iconCls: 'icon-patrimonio icon-pat-cancelado'
                }
            );
            this._toolbar.insert(
                3,
                '-'
            );
        }

        return this._toolbar;
    },

    closeSuspension: function() {
        var selection = this.getSelectionModel().getSelected();

        if(selection && selection.get('ativo')) {
            var rest = this.factoryRestful();

            rest.doRequest(
                rest.getRoute('close', false, 'POST', {
                    params: {
                        pk: selection.get('pk')
                    },
                    scope: this,
                    success: function(xhr) {
                        this.getStore().reload();
                    },
                    failure: function(xhr) {
                        Ext.Msg.show({
                            title: 'Finalizando Suspensão',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Funcionalidade indisponivel no momento.'
                        });
                    }
                })
            );
        }
        else if(selection && !selection.get('ativo'))
            Ext.Msg.show({
                title: 'Finalizando suspensão',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                msg: 'Esta suspensão já se encontra finalizada.'
            });
        else
            Ext.Msg.show({
                title: 'Finalizando suspensão',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Selecione uma suspensão para ser finalizada.'
            });
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {
                        header: 'Descricao',
                        dataIndex: 'unicode',
                        id: 'autoExpandColumn',
                        hidden: true
                    },
                    {
                        header: 'Suspenso por',
                        dataIndex: 'aberto_por_pessoa',
                        width: 325
                    },
                    {
                        header: 'Inicio da suspensão',
                        dataIndex: 'data_inicio',
                        width: 125,
                        renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')
                    },
                    {
                        header: 'Suspenso',
                        dataIndex: 'ativo',
                        width: 90,
                        renderer: function(value) { console.debug(value); return (value ? 'SIM' : 'NÃO'); }
                    },
                    {
                        header: 'Finalizado por',
                        dataIndex: 'fechado_por_pessoa',
                        width: 325
                    },
                    {
                        header: 'Fim da suspensão',
                        dataIndex: 'data_fim',
                        width: 125,
                        renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')
                    }
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'adm.patrimonio.SuspensaoRestful',
    'adm.patrimonio.SuspensaoGrid'
);

